import type { CliIO } from './io';

export type BrowserOpenResult =
  | { action: 'launch_requested'; reason: 'interactive_open' }
  | { action: 'skipped'; reason: 'no_browser_flag' }
  | { action: 'launch_failed'; reason: 'launcher_error' };

export type BrowserUrlField = 'editorUrl' | 'authUrl';

export const requestBrowserOpen = async ({
  url,
  urlField,
  isBrowserDisabled,
  io,
  launch,
}: {
  url: string;
  urlField: BrowserUrlField;
  isBrowserDisabled: boolean;
  io: CliIO;
  launch?: (url: string) => Promise<unknown>;
}): Promise<BrowserOpenResult> => {
  const publicUrl = new URL(url);
  publicUrl.hash = '';
  if (isBrowserDisabled) {
    io.writeProgress(
      `Browser launch skipped (--no-browser). Open the ${urlField} from the command result to authorize ${publicUrl}.`,
    );
    return { action: 'skipped', reason: 'no_browser_flag' };
  }
  try {
    const open = launch ?? (await import('open')).default;
    await open(url);
    io.writeProgress(`Requested browser launch for ${publicUrl}`);
    return { action: 'launch_requested', reason: 'interactive_open' };
  } catch {
    io.writeProgress(
      `Browser launch failed. Open the ${urlField} from the command result to authorize ${publicUrl}.`,
    );
    return { action: 'launch_failed', reason: 'launcher_error' };
  }
};
